152	/**
153	 * Toggle an inline mark (bold/italic/strikethrough/code). When the selection
154	 * already sits in the corresponding mark, strip the surrounding delimiter
155	 * nodes instead of nesting a new pair. Deleting the actual delimiter child
156	 * ranges handles the differing delimiter lengths (`**` vs `` ` ``) automatically.
157	 */
158	function toggleMark(view: EditorView, command: MarkCommand) {
159	  const { token, wrapper, delimiter } = MARKS[command];
160	  const marks = findWrappedDelimiters(view, wrapper, delimiter, 2);
161	  if (marks) {
162	    const opening = marks[0];
163	    const closing = marks[marks.length - 1];
164	    view.dispatch({
165	      changes: [
166	        { from: closing.from, to: closing.to, insert: "" },
167	        { from: opening.from, to: opening.to, insert: "" },
168	      ],
169	    });
170	    return;
171	  }
172	  // Empty pair: a cursor sitting between freshly inserted delimiters (`**|**`).
173	  // Markdown never parses an empty mark as that mark (bare `****` is a
174	  // horizontal rule, `~~~~` a tilde code fence, `` `` `` plain text), so the
175	  // tree probe above can't see it — check the text instead. Without this,
176	  // re-clicking the button keeps nesting new pairs.
177	  const { from, to } = view.state.selection.main;
178	  if (
179	    from === to &&
180	    from >= token.length &&
181	    to + token.length <= view.state.doc.length &&
182	    view.state.sliceDoc(from - token.length, to + token.length) === token + token
183	  ) {
184	    const delFrom = from - token.length;
185	    const delTo = to + token.length;
186	    // Deleting is only unsafe when the adjacent tokens belong to parsed markup
187	    // reaching beyond the pair itself — e.g. an italic click between the `*`s
188	    // of a bold delimiter would destroy that bold. A construct contained
189	    // entirely in the deletion range (the `~~~~` the parser reads as an empty
190	    // tilde fence) is just this empty pair wearing another node name.
191	    const tree = syntaxTree(view.state);
192	    const blocking = (n: TreeNode) => {
193	      if (!DELIMITER_NODES.has(n.name)) return false;
194	      const construct = n.parent ?? n;
195	      return construct.from < delFrom || construct.to > delTo;
196	    };
197	    if (!blocking(tree.resolve(from, -1)) && !blocking(tree.resolve(to, 1))) {
198	      view.dispatch({
