215	function toggleCodeBlock(view: EditorView) {
216	  const { state } = view;
217	  const { from, to } = state.selection.main;
218	  const marks = findWrappedDelimiters(view, "FencedCode", "CodeMark", 1);
219	  if (marks) {
220	    const openLine = state.doc.lineAt(marks[0].from);
221	    // Delete each fence line together with its trailing newline. When the
222	    // closing fence is the document's last line there is no trailing newline
223	    // to take, so eat the preceding one instead — unless that would overlap
224	    // the opening deletion (empty block at end of document).
225	    const openEnd = Math.min(openLine.to + 1, state.doc.length);
226	    const specs = [{ from: openLine.from, to: openEnd, insert: "" }];
227	    if (marks.length >= 2) {
228	      const closeLine = state.doc.lineAt(marks[marks.length - 1].from);
229	      const closeIsLastLine = closeLine.to === state.doc.length;
230	      const closeTo = closeIsLastLine ? closeLine.to : closeLine.to + 1;
231	      const closeFrom = closeIsLastLine && closeLine.from - 1 >= openEnd ? closeLine.from - 1 : closeLine.from;
232	      specs.push({ from: closeFrom, to: closeTo, insert: "" });
233	    }
234	    const changes = state.changes(specs);
235	    view.dispatch({ changes, selection: state.selection.map(changes) });
236	    return;
237	  }
238	  const lineNumbers = selectedLineNumbers(view);
239	  const first = state.doc.line(lineNumbers[0]);
240	  const last = state.doc.line(lineNumbers[lineNumbers.length - 1]);
241	  const fence = "```";
242	  // Both selection ends sit within [first.from, last.to], so they shift by
243	  // exactly the opening `\`\`\`\n` — keeping the selection on the content (and
244	  // dropping a lone cursor inside the new empty block).
245	  view.dispatch({
246	    changes: [
247	      { from: first.from, insert: `${fence}\n` },
248	      { from: last.to, insert: `\n${fence}` },
249	    ],
