255	 * Toggle/convert the list mode of the selected lines. The three list modes are
256	 * mutually exclusive line states: when every selected line is already in the
257	 * requested mode the markers are removed; otherwise lines are converted to it
258	 * (replacing any other list marker, preserving indentation). With a multi-line
259	 * selection blank lines are left alone; a single selected blank line still gets
260	 * a marker so the "start a list on an empty line" flow works.
261	 */
262	function toggleListLine(view: EditorView, command: ListCommand) {
263	  const { state } = view;
264	  const lines = selectedLineNumbers(view).map((n) => state.doc.line(n));
265	  const nonBlank = lines.filter((line) => line.text.trim() !== "");
266	  const targets = lines.length === 1 || nonBlank.length === 0 ? lines : nonBlank;
267	  const infos = targets.map((line) => lineListInfo(line.text));
268	  const allOn = infos.every((info) => info.mode === command);
269	
270	  const specs: { from: number; to: number; insert: string }[] = [];
271	  for (const [i, line] of targets.entries()) {
272	    const { mode, indent, markerEnd } = infos[i];
273	    if (allOn) {
274	      specs.push({ from: line.from + indent, to: line.from + markerEnd, insert: "" });
275	    } else if (mode !== command) {
276	      // Lines already in the requested mode keep their marker untouched (a
277	      // checked `- [x]` stays checked when the selection is extended).
278	      const marker = command === "orderedList" ? `${i + 1}. ` : LIST_MARKERS[command];
279	      specs.push({ from: line.from + indent, to: line.from + markerEnd, insert: marker });
280	    }
281	  }
282	  if (specs.length === 0) return;
283	  const changes = state.changes(specs);
284	  // Map with assoc 1 so a cursor exactly at the insertion point (empty line)
285	  // lands after the inserted marker instead of staying at the line start.
286	  view.dispatch({ changes, selection: state.selection.map(changes, 1) });
287	}
