289	function setHeading(view: EditorView, level: number) {
290	  const line = view.state.doc.lineAt(view.state.selection.main.head);
291	  // Edit only the prefix region (not the whole line) so the cursor keeps its
292	  // place in the text instead of being flung to the line start by the mapping.
293	  const existing = HEADING_PREFIX.exec(line.text)?.[0].length ?? 0;
294	  const insert = level === 0 ? "" : `${"#".repeat(level)} `;
295	  const changes = view.state.changes({ from: line.from, to: line.from + existing, insert });
296	  view.dispatch({ changes, selection: view.state.selection.map(changes, 1) });
