299	/** Unwrap the link the head sits in to its label text. True when one was found. */
300	function unwrapLink(view: EditorView): boolean {
301	  const head = view.state.selection.main.head;
302	  const tree = syntaxTree(view.state);
303	  for (const n of ancestors(tree, head, -1)) {
304	    if (n.name !== "Link") continue;
305	    const marks = childRanges(n, "LinkMark");
306	    // marks[0] is `[`, marks[1] is `]` — the label sits between them.
307	    if (marks.length < 2) continue;
308	    const label = view.state.sliceDoc(marks[0].to, marks[1].from);
309	    const anchor = n.from + Math.max(0, Math.min(label.length, head - marks[0].to));
310	    view.dispatch({
311	      changes: { from: n.from, to: n.to, insert: label },
312	      selection: { anchor },
313	    });
314	    return true;
315	  }
316	  return false;
317	}
