319	export function createFormattingController(view: EditorView, listeners: Set<() => void>): FormattingController {
320	  return {
321	    run(command: EditorCommandId, ctx?: EditorCommandContext) {
322	      if (isMarkCommand(command)) return toggleMark(view, command);
323	      if (command === "codeBlock") return toggleCodeBlock(view);
324	      if (command === "bulletList" || command === "orderedList" || command === "taskList") {
325	        return toggleListLine(view, command);
326	      }
327	      if (command === "heading1") return setHeading(view, 1);
328	      if (command === "heading2") return setHeading(view, 2);
329	      if (command === "heading3") return setHeading(view, 3);
330	      if (command === "paragraph") return setHeading(view, 0);
331	      if (command === "link") {
332	        // Toggle: inside an existing link, unwrap it to its label.
333	        if (unwrapLink(view)) return;
334	        const { from, to } = view.state.selection.main;
335	        const url = ctx?.url ?? "";
336	        // Empty selection: the URL doubles as the label.
337	        const label = view.state.sliceDoc(from, to) || url;
338	        const insert = `[${label}](${url})`;
339	        view.dispatch({ changes: { from, to, insert }, selection: { anchor: from + insert.length } });
340	      }
341	    },
342	    getActiveFormats(): ActiveFormatState {
343	      const pos = view.state.selection.main.head;
344	      const tree = syntaxTree(view.state);
345	      const active: ActiveFormatState = { ...EMPTY_ACTIVE_FORMATS };
346	      // Inline marks come from the syntax tree around the cursor.
347	      for (const n of ancestors(tree, pos, -1)) {
348	        const mark = WRAPPER_TO_MARK[n.name];
349	        if (mark) active[mark] = true;
350	        else if (n.name === "Link") active.link = true;
351	        // The isEmptyMarkPair guard: a fresh empty strikethrough pair
352	        // (`~~|~~`) parses as a bare tilde code fence — don't light the
353	        // code-block button while the cursor sits in one.
354	        else if (n.name === "FencedCode" && !isEmptyMarkPair(view.state, n.from, n.to)) active.codeBlock = true;
355	      }
356	      // Line modes (lists, headings) come from the same line inspection the
357	      // toggles use, keeping highlight and toggle behavior in lockstep.
358	      const line = view.state.doc.lineAt(pos).text;
359	      const heading = HEADING_LINE.exec(line);
360	      if (heading) active.headingLevel = toToolbarHeadingLevel(heading[1].length);
361	      const { mode } = lineListInfo(line);
362	      if (mode) active[mode] = true;
363	      return active;
364	    },
365	    subscribe(listener: () => void) {
366	      listeners.add(listener);
367	      return () => {
368	        listeners.delete(listener);
369	      };
370	    },
371	  };
372	}
